class Solution {
public:
    std::vector<std::string> removeAnagrams(std::vector<std::string>& words) {
        std::vector<std::string> ans;
        std::string prev_key = "";
        for (const auto& w : words) {
            std::string k = w;
            std::sort(k.begin(), k.end());
            if (k != prev_key) {
                ans.push_back(w);
                prev_key = k;
            }
        }
        return ans;
    }
};

class Solution {
    public java.util.List<String> removeAnagrams(String[] words) {
        java.util.List<String> ans = new java.util.ArrayList<>();
        String prevKey = "";
        for (String w : words) {
            char[] chars = w.toCharArray();
            java.util.Arrays.sort(chars);
            String k = new String(chars);
            if (!k.equals(prevKey)) {
                ans.add(w);
                prevKey = k;
            }
        }
        return ans;
    }
}

var removeAnagrams = function(words) {
    const ans = [];
    let prevKey = "";
    for (const w of words) {
        const k = w.split("").sort().join("");
        if (k !== prevKey) {
            ans.push(w);
            prevKey = k;
        }
    }
    return ans;
};
